import {buildReport} from './model.mjs';
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stamp = t => t ? new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})+'（北京时间）' : '没有记录';
const get = async url => {const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error('无法读取已保存记录，请确认本地服务已启动。');return r.json();};
const names = ads => `<details class="names"><summary>查看对应广告 · ${ads.length} 条</summary><div class="name-scroll">${ads.map(a=>`<div class="name-row"><strong>Ad：${esc(a.name)}</strong><small>Ad Set：${esc(a.adset_name)}<br>Campaign：${esc(a.campaign_name)}</small></div>`).join('')}</div></details>`;
function card(item){const feature=item.title.includes('已开启但未允许');return `<article class="report-card"><h3>${esc(item.title)}</h3><p>${feature?'标准：不允许开启 → 保存配置：已开启。':'按已确认的首日规则核对，发现以下待处理项。'}影响 ${item.ads.length} 条广告。</p>${item.kind==='IDENTITY_REVIEW'?'<p>可能是合作广告，需核实身份；尚不能认定账号挂错。</p>':''}${names(item.ads)}${item.evidence?`<details><summary>查看页面核对依据</summary>${item.evidence.map(e=>`<pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(JSON.stringify(Object.fromEntries(Object.entries(e).filter(([k])=>!k.endsWith('_id'))),null,2))}</pre>`).join('')}</details>`:''}<p class="muted">${feature?'请核实是否允许这项功能。若确实不允许，由投手在 Meta 后台修正，再重新取数复查。':'请返回对应规则核实；更改规则需重新确认并保存版本。'}本报告会保留原检查结果。</p></article>`;}
try {
 const [versions,source]=await Promise.all([get('/api/versions'),get('/api/source-snapshot')]);
 const requested=new URLSearchParams(location.search).get('version');
 const v=requested?versions.find(x=>x.version===requested):versions.at(-1);
 if(!v)throw Error(requested?'没有找到这份首日版本。':'还没有保存首日版本，请先完成首次接入。');
 const r=buildReport(v,source);
 const groups=[['issues','01 · 需要处理的问题',r.issues,'在本版已执行的规则核对中，未发现不符项；检查不到的内容见下方。'],['rules','02 · 需要补充或确认的规则',r.rules,'本版已执行的规则范围内，没有发现待补规则。']];
 document.querySelector('#app').innerHTML=`<aside><a class="brand" href="../"><span class="brand-mark">e</span><span>demo<small>广告配置检查</small></span></a><div class="side-label">首次接入 → 首日报告</div><a class="report-link" href="../">查看 / 修改接入规则</a><a class="report-link active" href="#">第一天检查报告</a><a class="report-link" href="../phase-rules/">阶段规则 · 对话补充</a><div class="sidebar-note">本机保存的示例配置（虚构）<p>未重新拉取 Meta<br>未发送飞书</p></div></aside><div class="workspace"><header><div class="account">${esc(r.account)}</div><span class="badge amber">部分检查完成 · 仍有缺口</span></header><main><div class="page-title"><div class="eyebrow">DAY 1 · ${esc(r.version)}</div><h1>第一天检查报告</h1>${!v.excluded_capabilities?.includes("ai_creative_enhancements")?'<div class="notice amber">这是范围调整前保存的历史报告，保留当时的增强功能结果。当前 AI 增强已移出检查范围，新生成的检查报告不再包含这些项。</div>':''}<p>接入已完成。先处理规则不符，检查不到的内容单独保留。</p><p class="meta">配置采集：${stamp(r.captured_at)}<br>首日版本保存：${stamp(r.created_at)} · 确认人：${esc(r.reviewer)}</p></div><div class="notice subtle"><strong>这份报告来自你保存的接入版本；默认数据全部为虚构示例。</strong><p>展示保存当时的配置与确认规则。首次接入没有上一期对照，因此不显示“本次调整”，也不把现有广告当作新增。打开页面不会刷新广告数据。</p></div><div class="metrics three"><div class="metric"><strong>${r.issues.length}</strong><span>组问题 · 影响 ${r.affected} 条广告（去重）</span></div><div class="metric"><strong>${r.rules.length}</strong><span>组规则需要处理</span></div><div class="metric"><strong>${r.total}</strong><span>条广告纳入本次保存范围</span></div></div>${groups.map(([id,title,items,empty])=>`<section id="${id}"><h2>${title}</h2>${items.length?items.map(card).join(''):`<p>${empty}</p>`}</section>`).join('')}<section><h2>03 · 这些检查不到 / 尚未完成</h2><div class="gap-list">${r.limitations.map(t=>`<div><p>${esc(t)}</p></div>`).join('')}</div>${r.gaps.map(card).join('')}<p>语言规则已确认，但未完成全部外语文案核验。人群、版位、出价和归因等首日配置作为后续对照，不代表策略正确性已逐项审核。阶段关键词可从左侧补充；历史快照试查与这份已保存报告分别展示。</p></section><section><h2>接下来怎么处理</h2><p>允许的例外：返回接入规则，修改后重新确认并保存。确实不该开启的设置：由投手在 Meta 后台修正，重新取数后复查；本页不会改广告，也不会自动关闭问题。</p><div class="actions"><a class="primary" href="../">查看 / 修改接入规则</a><button class="secondary" id="download">下载这份报告</button></div><p class="muted">当前已接通：保存接入 → 查看首日报告（示例数据）。报告内反馈、重新取数复查和发送飞书，尚未在此页接通。</p></section></main></div>`;
 document.querySelector('#download').onclick=()=>{const output={account:r.account,version:r.version,source_captured_at:r.captured_at,baseline_saved_at:r.created_at,scope_ads:r.total,issues:r.issues.map(x=>({title:x.title,ads:x.ads.map(a=>({ad:a.name,adset:a.adset_name,campaign:a.campaign_name}))})),rule_gaps:r.rules.map(x=>({title:x.title,ads:x.ads.map(a=>a.name)})),uncheckable:[...r.limitations,...r.gaps.map(x=>x.title)]};const url=URL.createObjectURL(new Blob([JSON.stringify(output,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`${r.account}-首日报告-${r.version}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
} catch(e){document.querySelector('#app').innerHTML=`<div class="loading"><h1>暂时无法打开首日报告</h1><p>${esc(e.message)}</p><a href="../">返回首次接入</a></div>`;}
